      546:     /* Buffer may already have been destroyed elsewhere. This is harmless. */
      547:     if (out == NULL) {
      548: 	Py_INCREF(Py_None);
      549: 	return(Py_None);
      550:     }
      551: 
>>>   552:     c_retval = xmlOutputBufferClose(out);
